/**
 * PublishToWechatMpRequest 一站式发布 Markdown 或 HTML 内容到微信公众号。
 *  流程：按格式预处理正文 → 封面上传 → 创建/更新草稿 → 可选群发。
 */
export interface PublishToWechatMpRequest {
  /**
   * 文章作者。
   */
  author?: string;
  /**
   * 客户端缓存的已发布文章（往期推荐功能的回退数据源）。
   */
  cached_articles?: PublishedArticleInfo[];
  /**
   * Markdown 或 HTML 正文内容（必填）。
   */
  content?: string;
  /**
   * 正文格式。未指定时按 Markdown 处理，以兼容旧客户端。
   */
  content_format?: ContentFormat;
  /**
   * 原文链接 URL。
   */
  content_source_url?: string;
  /**
   * 封面图 URL，将自动上传为微信 thumb 素材。
   */
  cover_url?: string;
  /**
   * 是否返回调试日志。
   */
  debug?: boolean;
  /**
   * 文章摘要，未填写时微信默认截取正文前 120 字。
   */
  digest?: string;
  /**
   * 正文中的图片映射：本地路径/标识 → 已上传的微信图片 URL。
   */
  image_map?: Record<string, string>;
  /**
   * 是否开启评论功能。
   */
  need_open_comment?: boolean;
  /**
   * 是否在正文中显示封面图。
   */
  show_cover_pic?: boolean;
  /**
   * 发布目标：草稿或群发。
   */
  target?: PublishToWechatMpTarget;
  /**
   * 排版模板/主题 ID。
   */
  template_id?: string;
  /**
   * 文章标题（必填）。
   */
  title?: string;
  /**
   * 微信公众号 API 调用凭证（必填）。
   *  详见 WechatMpCredentials 设计说明（types.proto）。
   */
  wechat_mp_credentials?: WechatMpCredentials;
}

