/**
 * CancelVideoTaskRequest 取消正在执行的视频生成任务。
 *  仅 PENDING / GENERATING_SCRIPT / GENERATING_ASSETS / COMPOSITING 状态的任务可取消。
 */
export interface CancelVideoTaskRequest {
  task_id?: string;
}

export interface CancelVideoTaskResponse {
  /**
   * 取消后的任务状态。
   */
  task?: VideoTask;
}

/**
 * CreateVideoRequest 基于脚本和素材合成视频。
 *  支持两种模式：
 *    1. 指定 task_id —— 使用已有 VideoTask 中 LLM 生成的脚本
 *    2. 指定 project_id + script —— 直接提供脚本创建视频
 */
export interface CreateVideoRequest {
  /**
   * 需要包含在视频中的素材 ID 列表（图片、音频等）。
   */
  asset_ids?: string[];
  /**
   * 输出分辨率高度（像素），默认 1080。
   */
  height?: number;
  /**
   * 所属项目 ID，与 task_id 互斥时使用。
   */
  project_id?: string;
  /**
   * 直接提供的视频脚本文本，与 task_id 互斥时使用。
   */
  script?: string;
  /**
   * 视频风格。
   */
  style?: VideoStyle;
  /**
   * 已有的视频任务 ID（包含 LLM 生成的脚本），与 project_id+script 互斥。
   */
  task_id?: string;
  /**
   * 输出分辨率宽度（像素），默认 1920。
   */
  width?: number;
}

/**
 * CreateVideoResponse 返回创建的视频任务。
 *  视频合成为异步操作，通过 GetVideoTask 轮询进度。
 */
export interface CreateVideoResponse {
  /**
   * VideoTask represents a video generation job.
   *  视频生成是异步任务，客户端提交后通过轮询 GetVideoTask 获取进度。
   */
  task?: VideoTask;
}

/**
 * DeleteVideoTaskRequest 删除视频任务及其生成的视频文件。
 */
export interface DeleteVideoTaskRequest {
  task_id?: string;
}

export type DeleteVideoTaskResponse = unknown;

/**
 * GenerateScriptRequest 基于主题或已有文章，调用 LLM 生成视频脚本。
 */
export interface GenerateScriptRequest {
  /**
   * 从已有文章派生脚本，与 topic 二选一。
   *  指定后 LLM 会基于文章内容改编为视频脚本。
   */
  article_id?: string;
  /**
   * 输出语言，BCP 47 格式。
   */
  language?: string;
  /**
   * 所属项目 ID。
   */
  project_id?: string;
  /**
   * 补充要求，例如 "面向初学者"、"突出产品优势"。
   */
  requirements?: string;
  /**
   * 视频风格，决定脚本的结构和节奏。
   */
  style?: VideoStyle;
  /**
   * 目标视频时长（秒），LLM 会据此控制脚本篇幅。
   */
  target_duration_seconds?: number;
  /**
   * 视频主题，与 article_id 二选一。
   */
  topic?: string;
}

/**
 * GenerateScriptResponse 是 GenerateScript 的流式响应。
 */
export interface GenerateScriptResponse {
  /**
   * 是否生成完毕。
   */
  done?: boolean;
  /**
   * 流式事件，携带内容片段、状态更新、Token 用量或错误信息。
   */
  event?: StreamEvent;
  /**
   * 完整的视频任务实体，仅在 done=true 时填充。
   */
  task?: VideoTask;
}

export interface GetVideoTaskRequest {
  task_id?: string;
}

export interface GetVideoTaskResponse {
  /**
   * VideoTask represents a video generation job.
   *  视频生成是异步任务，客户端提交后通过轮询 GetVideoTask 获取进度。
   */
  task?: VideoTask;
}

export interface ListVideoTasksRequest {
  /**
   * 每页返回数量，默认 20，最大 100。
   */
  page_size?: number;
  /**
   * 分页令牌。
   */
  page_token?: string;
  /**
   * 按项目过滤。
   */
  project_id?: string;
  /**
   * 按任务状态过滤。
   */
  status?: VideoStatus | null;
}

export interface ListVideoTasksResponse {
  next_page_token?: string;
  tasks?: VideoTask[];
  total_count?: number;
}

/**
 * VideoStatus indicates the state of a video generation task.
 *  视频生成是异步多阶段流程，状态反映当前所处阶段。
 *  状态流转: PENDING → GENERATING_SCRIPT → GENERATING_ASSETS → COMPOSITING → COMPLETED / FAILED
 */
export type VideoStatus = "VIDEO_STATUS_UNSPECIFIED" | "VIDEO_STATUS_PENDING" | "VIDEO_STATUS_GENERATING_SCRIPT" | "VIDEO_STATUS_GENERATING_ASSETS" | "VIDEO_STATUS_COMPOSITING" | "VIDEO_STATUS_COMPLETED" | "VIDEO_STATUS_FAILED";

/**
 * VideoStyle indicates the visual style for video generation.
 *  不同风格对应不同的视频生成流水线和模板。
 */
export type VideoStyle = "VIDEO_STYLE_UNSPECIFIED" | "VIDEO_STYLE_SLIDESHOW" | "VIDEO_STYLE_TALKING_HEAD" | "VIDEO_STYLE_EXPLAINER" | "VIDEO_STYLE_HIGHLIGHT";

