/**
 * SourceNote is a short, safe explanation of used, omitted, or uncertain
 *  source material. External-source fields are future-reserved and absent in
 *  the current release.
 */
export interface SourceNote {
  /**
   * (OPTIONAL) Conditional. Future-reserved canonical HTTPS URL; currently absent.
   */
  canonical_url?: string | null;
  /**
   * (OPTIONAL) Conditional. Future-reserved retrieved-content SHA-256; currently absent.
   */
  content_sha256?: string | null;
  /**
   * (OPTIONAL) Conditional. Future-reserved external source identifier; currently absent.
   */
  external_source_id?: string | null;
  /**
   * Required. Safe note kind; EXTERNAL_SOURCE is future-reserved.
   */
  kind: SourceNoteKind;
  /**
   * (OPTIONAL) Optional. Opaque source material identifier when attributable.
   */
  material_id?: string | null;
  /**
   * (OPTIONAL) Optional. Future-reserved source publication time; currently absent.
   */
  published_at?: Timestamp;
  /**
   * (OPTIONAL) Conditional. Future-reserved publisher; currently absent.
   */
  publisher?: string | null;
  /**
   * (OPTIONAL) Conditional. Future-reserved retrieval time; currently absent.
   */
  retrieved_at?: Timestamp;
  /**
   * (OPTIONAL) Optional. Safe page, slide, sheet, cell, or image-region description.
   */
  source_location?: string | null;
  /**
   * Required. User-understandable short explanation.
   */
  summary: string;
  /**
   * (OPTIONAL) Conditional. Future-reserved external source title; currently absent.
   */
  title?: string | null;
}

/**
 * SourceNoteKind identifies a safe, user-facing source note.
 *  EXTERNAL_SOURCE is future-reserved and never returned in the current release.
 */
export type SourceNoteKind = "SOURCE_NOTE_KIND_UNSPECIFIED" | "SOURCE_NOTE_KIND_SOURCE" | "SOURCE_NOTE_KIND_OMITTED_CONTENT" | "SOURCE_NOTE_KIND_UNCERTAINTY" | "SOURCE_NOTE_KIND_EXTERNAL_SOURCE";

