/**
 * AccountStorageProtection is the authoritative user-scoped singleton that
 *  tells clients whether hosted content remains protected.
 */
export interface AccountStorageProtection {
  /**
   * (OPTIONAL) Conditional. Present when a current settled storage fact exists.
   */
  cost_summary?: CostSummary;
  /**
   * (OPTIONAL) Conditional. Required in PROTECTED or EXPIRY_CLEANUP.
   */
  expires_at?: Timestamp;
  /**
   * Required. Time the server last recalculated the state from billing facts.
   */
  last_checked_at: Timestamp;
  /**
   * (OPTIONAL) Conditional. Required in PROTECTED or EXPIRY_CLEANUP.
   */
  protected_at?: Timestamp;
  /**
   * Required. Stable reason for the current state.
   */
  reason: AccountStorageProtectionReason;
  /**
   * Required. Server-computed nonnegative seconds; zero outside PROTECTED.
   */
  remaining_seconds: string;
  /**
   * Required. Persisted storage protection state.
   */
  state: AccountStorageProtectionState;
}

/**
 * AccountStorageProtectionReason is the stable reason for the current account
 *  storage protection state.
 */
export type AccountStorageProtectionReason = "ACCOUNT_STORAGE_PROTECTION_REASON_UNSPECIFIED" | "ACCOUNT_STORAGE_PROTECTION_REASON_NORMAL_ACCOUNT" | "ACCOUNT_STORAGE_PROTECTION_REASON_STORAGE_PERIOD_SETTLED" | "ACCOUNT_STORAGE_PROTECTION_REASON_STORAGE_ADJUSTMENT_SETTLED" | "ACCOUNT_STORAGE_PROTECTION_REASON_BALANCE_GRACE" | "ACCOUNT_STORAGE_PROTECTION_REASON_PROTECTION_EXPIRED" | "ACCOUNT_STORAGE_PROTECTION_REASON_CLEANUP_COMPLETE";

/**
 * AccountStorageProtectionState is the persisted account protection state.
 */
export type AccountStorageProtectionState = "ACCOUNT_STORAGE_PROTECTION_STATE_UNSPECIFIED" | "ACCOUNT_STORAGE_PROTECTION_STATE_NORMAL" | "ACCOUNT_STORAGE_PROTECTION_STATE_PROTECTED" | "ACCOUNT_STORAGE_PROTECTION_STATE_EXPIRY_CLEANUP" | "ACCOUNT_STORAGE_PROTECTION_STATE_CLOSED";

