export interface GetMaterialRequest {
  /**
   * Required. Opaque material identifier.
   */
  material_id: string;
  /**
   * Required. Owner path; accepts me or the authenticated user's identifier.
   */
  user_id: string;
}

export interface GetMaterialResponse {
  /**
   * Required. Current authoritative material fact.
   */
  material: Material;
}

export interface GetStorageProtectionRequest {
  /**
   * Required. Owner path; accepts me or the authenticated user's identifier.
   */
  user_id: string;
}

export interface GetStorageProtectionResponse {
  /**
   * Required. Current user-scoped storage protection fact.
   */
  storage_protection: AccountStorageProtection;
}

export interface GetUploadRequest {
  /**
   * Required. Opaque PinPage upload identifier.
   */
  upload_id: string;
  /**
   * Required. Owner path; accepts me or the authenticated user's identifier.
   */
  user_id: string;
}

export interface GetUploadResponse {
  /**
   * (OPTIONAL) Optional. Required when the upload completed and created a material.
   */
  material?: Material;
  /**
   * Required. Current durable upload session.
   */
  upload: UploadSession;
}

/**
 * Material is a validated, owner-scoped source asset created only after a
 *  multipart upload is completed and the full object has been verified.
 */
export interface Material {
  /**
   * Required. File-service estimate and settlement summary.
   */
  cost_summary: CostSummary;
  /**
   * Required. Material creation time after multipart completion.
   */
  created_at: Timestamp;
  /**
   * Required. MIME detected from the complete uploaded object.
   */
  detected_media_type: string;
  /**
   * Required. Sanitized user-visible basename without a device path.
   */
  display_name: string;
  /**
   * (OPTIONAL) Conditional. Required in REJECTED or FAILED; stable and provider-safe.
   */
  failure_reason?: string | null;
  /**
   * Required. Opaque material identifier.
   */
  material_id: string;
  /**
   * (OPTIONAL) Conditional. Present after the material is retained by a page.
   */
  page_id?: string | null;
  /**
   * Required. Lowercase hexadecimal SHA-256 of the complete object.
   */
  sha256: string;
  /**
   * Required. Actual object size confirmed by storage.
   */
  size_bytes: string;
  /**
   * Required. Current validation and parsing lifecycle state.
   */
  status: MaterialStatus;
  /**
   * Required. Time the material fact last changed.
   */
  updated_at: Timestamp;
}

/**
 * MaterialDeletionResult confirms immediate access revocation for an unbound
 *  material. Physical cleanup continues asynchronously.
 */
export interface MaterialDeletionResult {
  /**
   * Required. Time logical access revocation became effective.
   */
  accepted_at: Timestamp;
  /**
   * Required. Opaque deleted material identifier.
   */
  material_id: string;
}

/**
 * MaterialStatus is the public processing lifecycle of an uploaded material.
 */
export type MaterialStatus = "MATERIAL_STATUS_UNSPECIFIED" | "MATERIAL_STATUS_SCANNING" | "MATERIAL_STATUS_PARSING" | "MATERIAL_STATUS_READY" | "MATERIAL_STATUS_REJECTED" | "MATERIAL_STATUS_FAILED" | "MATERIAL_STATUS_DELETED";

export interface SignUploadPartsRequest {
  /**
   * Required. One to one hundred unique numbers within the session part plan.
   */
  part_numbers: number[];
  /**
   * Required. OPEN upload session identifier.
   */
  upload_id: string;
  /**
   * Required. Owner path; accepts me or the authenticated user's identifier.
   */
  user_id: string;
}

export interface SignUploadPartsResponse {
  /**
   * Required. One short-lived signed capability per requested part.
   */
  parts: SignedUploadPart[];
}

/**
 * SignedUploadPart is a short-lived, owner-authorized capability for uploading
 *  one part. URLs and headers must never be logged or forwarded.
 */
export interface SignedUploadPart {
  /**
   * Required. Expiry time of put_url.
   */
  expires_at: Timestamp;
  /**
   * Required. Multipart part number.
   */
  part_number: number;
  /**
   * Required. Short-lived HTTPS bearer URL for this part.
   */
  put_url: string;
  /**
   * Required. Headers that must be sent byte-for-byte; empty when none.
   */
  required_headers: Record<string, string>;
}

export interface SignedUploadPartRequiredHeadersEntry {
  key?: string;
  value?: string;
}

/**
 * UploadEstimate is a durable, short-lived batch estimate created before any
 *  multipart upload, signed URL, reserve, or object exists.
 */
export interface UploadEstimate {
  /**
   * Required. Immutable maximum net charge confirmed for the original batch.
   */
  authorized_max_credit: string;
  /**
   * Required. Whether the balance covers authorized_max_credit.
   */
  balance_sufficient: boolean;
  /**
   * Required. Durable estimate creation time.
   */
  created_at: Timestamp;
  /**
   * Required. Wallet balance snapshot at estimate creation.
   */
  current_balance_credit: string;
  /**
   * Required. Time after which remaining items cannot be consumed.
   */
  expires_at: Timestamp;
  /**
   * Required. SHA-256 of the original normalized declarations.
   */
  input_fingerprint: string;
  /**
   * Required. Original ordered item positions, including purged tombstones.
   */
  items: UploadEstimateItem[];
  /**
   * Required. Public file-service pricing contract version.
   */
  pricing_version: string;
  /**
   * Required. File estimate across current non-purged items.
   */
  remaining_estimated_file_credit: string;
  /**
   * Required. Count of current non-purged items.
   */
  remaining_file_count: number;
  /**
   * Required. Declared bytes across current non-purged items.
   */
  remaining_total_size_bytes: string;
  /**
   * Required. Derived batch lifecycle state.
   */
  state: UploadEstimateState;
  /**
   * Required. Opaque upload estimate identifier.
   */
  upload_estimate_id: string;
}

/**
 * UploadEstimateDeclaration is one client file declaration priced as an
 *  immutable item before any multipart session or signed URL exists.
 */
export interface UploadEstimateDeclaration {
  /**
   * Required. Client-declared MIME used for validation and estimation.
   */
  declared_media_type: string;
  /**
   * Required. Lowercase hexadecimal SHA-256 of the complete file.
   */
  declared_sha256: string;
  /**
   * Required. Declared complete-file size, from 1 to 50,000,000 bytes.
   */
  declared_size_bytes: string;
  /**
   * Required. Sanitized user-visible basename, from 1 to 255 characters.
   */
  display_name: string;
}

/**
 * UploadEstimateItem is one immutable declared file position in an upload
 *  estimate batch. Content-bearing fields are suppressed after CONTENT_PURGED.
 */
export interface UploadEstimateItem {
  /**
   * (OPTIONAL) Conditional. Required in CONSUMED and omitted after CONTENT_PURGED.
   */
  consumed_upload_id?: string | null;
  /**
   * (OPTIONAL) Conditional. Required in AVAILABLE or CONSUMED; omitted after CONTENT_PURGED.
   */
  declared_media_type?: string | null;
  /**
   * (OPTIONAL) Conditional. Required in AVAILABLE or CONSUMED; omitted after CONTENT_PURGED.
   */
  declared_sha256?: string | null;
  /**
   * (OPTIONAL) Conditional. Required in AVAILABLE or CONSUMED; omitted after CONTENT_PURGED.
   */
  declared_size_bytes?: string | null;
  /**
   * (OPTIONAL) Conditional. Required in AVAILABLE or CONSUMED; omitted after CONTENT_PURGED.
   */
  display_name?: string | null;
  /**
   * Required. Opaque item identifier allocated within the estimate.
   */
  estimate_item_id: string;
  /**
   * Required. Current item lifecycle state.
   */
  state: UploadEstimateItemState;
}

/**
 * UploadEstimateItemState is the lifecycle of a position in an upload
 *  estimate. CONTENT_PURGED suppresses all content-bearing fields.
 */
export type UploadEstimateItemState = "UPLOAD_ESTIMATE_ITEM_STATE_UNSPECIFIED" | "UPLOAD_ESTIMATE_ITEM_STATE_AVAILABLE" | "UPLOAD_ESTIMATE_ITEM_STATE_CONSUMED" | "UPLOAD_ESTIMATE_ITEM_STATE_CONTENT_PURGED";

/**
 * UploadEstimateState is the derived lifecycle of an upload estimate batch.
 */
export type UploadEstimateState = "UPLOAD_ESTIMATE_STATE_UNSPECIFIED" | "UPLOAD_ESTIMATE_STATE_ACTIVE" | "UPLOAD_ESTIMATE_STATE_PARTIALLY_CONSUMED" | "UPLOAD_ESTIMATE_STATE_CONSUMED" | "UPLOAD_ESTIMATE_STATE_EXPIRED";

/**
 * UploadSession is the durable, resumable public multipart fact. It excludes
 *  provider upload identifiers, object-storage keys, and credentials.
 */
export interface UploadSession {
  /**
   * Required. FILE_UPLOAD estimate, authorization, and settlement summary.
   */
  cost_summary: CostSummary;
  /**
   * Required. Durable session creation time.
   */
  created_at: Timestamp;
  /**
   * Required. Declared MIME copied from the immutable estimate item.
   */
  declared_media_type: string;
  /**
   * Required. Declared complete-file SHA-256 copied from the estimate item.
   */
  declared_sha256: string;
  /**
   * Required. Declared bytes copied from the immutable estimate item.
   */
  declared_size_bytes: string;
  /**
   * Required. Sanitized display name copied from the immutable estimate item.
   */
  display_name: string;
  /**
   * Required. Expiry time for an unfinished session.
   */
  expires_at: Timestamp;
  /**
   * (OPTIONAL) Conditional. Required in REJECTED or FAILED; stable and provider-safe.
   */
  failure_reason?: string | null;
  /**
   * (OPTIONAL) Conditional. Required in COMPLETED and absent in other states.
   */
  material_id?: string | null;
  /**
   * (OPTIONAL) Conditional. Present with part_size_bytes after the multipart plan is established.
   */
  part_count?: number | null;
  /**
   * (OPTIONAL) Conditional. Present with part_count after the multipart plan is established.
   */
  part_size_bytes?: string | null;
  /**
   * Required. Current public upload lifecycle.
   */
  status: UploadStatus;
  /**
   * Required. Opaque PinPage upload session identifier.
   */
  upload_id: string;
  /**
   * Required. Authoritative persisted parts; an empty list before any upload.
   */
  uploaded_parts: UploadedPart[];
}

/**
 * UploadStatus is the public multipart upload lifecycle.
 */
export type UploadStatus = "UPLOAD_STATUS_UNSPECIFIED" | "UPLOAD_STATUS_OPENING" | "UPLOAD_STATUS_OPEN" | "UPLOAD_STATUS_COMPLETING" | "UPLOAD_STATUS_COMPLETED" | "UPLOAD_STATUS_ABORTING" | "UPLOAD_STATUS_ABORTED" | "UPLOAD_STATUS_EXPIRED" | "UPLOAD_STATUS_REJECTED" | "UPLOAD_STATUS_FAILED";

/**
 * UploadedPart is one authoritative part confirmed by object storage and
 *  persisted into the upload session.
 */
export interface UploadedPart {
  /**
   * Required. Provider ETag preserved byte-for-byte.
   */
  etag: string;
  /**
   * Required. Multipart part number.
   */
  part_number: number;
  /**
   * Required. Actual part size confirmed by object storage.
   */
  size_bytes: string;
}

